insert into public.guest_notes (id, property_id, guest_id, body, created_by)
values
  ('note_guest_radha_arora_demo', '00000000-0000-4000-8000-000000000001', 'guest_radha_arora_demo', 'Fictional executive VIP demo profile based only on public professional and travel preference signals. Guest is on property for an executive hospitality innovation review and is likely to value discreet, polished service, exact property details, sense of place, local cultural expression, dining, wellness, and experiences that feel specific to Rosewood Sand Hill rather than generic luxury.', 's_001'),
  ('note_g_0421', '00000000-0000-4000-8000-000000000001', 'g_0421', 'Returning Founder guest. Prefers quiet service, handwritten notes, and late breakfast on the terrace.', 's_001'),
  ('note_g_0422', '00000000-0000-4000-8000-000000000001', 'g_0422', 'In town for a board dinner. Assistant asked that no calls be routed before 8:30 AM.', 's_001'),
  ('note_g_0423', '00000000-0000-4000-8000-000000000001', 'g_0423', 'Travelling with parents and infant. Keep routing simple and avoid long waits at reception.', 's_001'),
  ('note_g_0424', '00000000-0000-4000-8000-000000000001', 'g_0424', 'Asked for discreet dining suggestions with outdoor seating.', 's_001'),
  ('note_g_0425', '00000000-0000-4000-8000-000000000001', 'g_0425', 'Quick overnight. Needs pressed jacket before 7:00 AM.', 's_001'),
  ('note_g_0426', '00000000-0000-4000-8000-000000000001', 'g_0426', 'Family stay. Security asked for arrival discretion due to public profile.', 's_001'),
  ('note_g_0501', '00000000-0000-4000-8000-000000000001', 'g_0501', 'Couple values privacy. Use text updates through concierge desk only.', 's_001'),
  ('note_g_0502', '00000000-0000-4000-8000-000000000001', 'g_0502', 'Preparing for litigation meetings. Keep room service precise and quick.', 's_001'),
  ('note_g_0503', '00000000-0000-4000-8000-000000000001', 'g_0503', 'Prefers staff to address her by first name after first greeting.', 's_001'),
  ('note_g_0504', '00000000-0000-4000-8000-000000000001', 'g_0504', 'Interested in late afternoon activities and quiet dinner venues.', 's_001'),
  ('note_g_0505', '00000000-0000-4000-8000-000000000001', 'g_0505', 'Departure transfer at 1:15 PM. Bags should be staged by noon.', 's_001'),
  ('note_g_0506', '00000000-0000-4000-8000-000000000001', 'g_0506', 'Keeps early schedule. Breakfast tray requested before 6:30 AM.', 's_001'),
  ('note_g_0507', '00000000-0000-4000-8000-000000000001', 'g_0507', 'Regular guest. Team should coordinate movements discreetly through side entrance.', 's_001'),
  ('note_g_0508', '00000000-0000-4000-8000-000000000001', 'g_0508', 'Open to concierge recommendations; tends to book same-day experiences.', 's_001'),
  ('note_g_0601', '00000000-0000-4000-8000-000000000001', 'g_0601', 'Anniversary amenity should be elegant, not theatrical.', 's_001'),
  ('note_g_0602', '00000000-0000-4000-8000-000000000001', 'g_0602', 'Conference attendee. Prefers simple check-in and no upsell.', 's_001'),
  ('note_g_0603', '00000000-0000-4000-8000-000000000001', 'g_0603', 'First stay. Concierge should pre-build an arts itinerary.', 's_001'),
  ('note_g_0604', '00000000-0000-4000-8000-000000000001', 'g_0604', 'High-touch arrival. Manager to greet privately in the library.', 's_001'),
  ('note_g_0605', '00000000-0000-4000-8000-000000000001', 'g_0605', 'Assistant will send final schedule the day before arrival.', 's_001'),
  ('note_g_0606', '00000000-0000-4000-8000-000000000001', 'g_0606', 'Family celebration. Avoid red roses; guest prefers white orchids.', 's_001'),
  ('note_g_0701', '00000000-0000-4000-8000-000000000001', 'g_0701', 'Lost-and-found follow-up completed by concierge.', 's_001'),
  ('note_g_0702', '00000000-0000-4000-8000-000000000001', 'g_0702', 'Asked to be contacted only by assistant for future stays.', 's_001'),
